"""Legacy Meridian CRM numeric division compatibility."""

from __future__ import annotations


def _numeric_coerce(value: object) -> float:
    """Apply legacy numeric-context coercion without raising exceptions."""
    if value is None or value == "":
        return 0.0

    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using Meridian CRM's division-by-zero behavior."""
    numerator = _numeric_coerce(a)
    divisor = _numeric_coerce(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / divisor, []
    except (ArithmeticError, OverflowError, ValueError):
        return 0.0, ["SCRIPT_DIV0"]
